"use client"

import { useEffect, useId, useRef, useState } from "react"

/** Renders Mermaid source to SVG.
 *
 *  Mermaid is imported dynamically — it's a large library and nothing should
 *  pay for it until a diagram actually appears on screen.
 *
 *  `securityLevel: "strict"` matters here: diagram source is authored by an
 *  admin or generated by the AI pipeline, and strict mode stops HTML in node
 *  labels from being executed.
 *
 *  Invalid source is expected rather than exceptional (a model can emit
 *  malformed Mermaid), so a parse failure degrades to a readable message
 *  instead of throwing. `showSource` surfaces the parser error and the raw
 *  code — useful in the editor, noise for a student. */
export default function MermaidDiagram({
  code,
  className,
  showSource = false,
}: {
  code: string
  className?: string
  showSource?: boolean
}) {
  const [svg, setSvg] = useState("")
  const [error, setError] = useState<string | null>(null)

  // Mermaid uses this as a DOM id, so it has to be selector-safe —
  // useId() returns colon-wrapped values like ":r0:".
  const reactId = useId()
  const idRef = useRef(`mermaid-${reactId.replace(/[^a-zA-Z0-9]/g, "")}`)

  useEffect(() => {
    let cancelled = false
    const source = code.trim()

    if (!source) {
      setSvg("")
      setError(null)
      return
    }

    void (async () => {
      try {
        const mermaid = (await import("mermaid")).default
        mermaid.initialize({
          startOnLoad:  false,
          securityLevel: "strict",
          theme:        "neutral",
          fontFamily:   "var(--font-body), system-ui, sans-serif",
        })
        const { svg } = await mermaid.render(idRef.current, source)
        if (cancelled) return
        setSvg(svg)
        setError(null)
      } catch (e) {
        if (cancelled) return
        setSvg("")
        setError(e instanceof Error ? e.message : "Could not render this diagram.")
        // A failed parse can leave mermaid's temporary render node behind.
        document.getElementById(idRef.current)?.remove()
      }
    })()

    return () => { cancelled = true }
  }, [code])

  if (error) {
    return (
      <div className={`rounded-[10px] border border-amber-200 bg-amber-50 px-4 py-3 ${className ?? ""}`}>
        <p className="font-body text-[12px] font-medium text-amber-900">
          This diagram could not be rendered.
        </p>
        {showSource && (
          <>
            <p className="mt-1 font-body text-[11px] text-amber-800">{error}</p>
            <pre className="mt-2 overflow-x-auto rounded bg-white/70 p-2 font-mono text-[11px] text-amber-900">
              {code}
            </pre>
          </>
        )}
      </div>
    )
  }

  if (!svg) {
    return (
      <div className={`h-24 animate-pulse rounded-[10px] bg-[#F0EEE9] ${className ?? ""}`} />
    )
  }

  // Mermaid's own output, rendered in strict mode.
  return (
    <div
      className={`[&_svg]:mx-auto [&_svg]:h-auto [&_svg]:max-w-full ${className ?? ""}`}
      dangerouslySetInnerHTML={{ __html: svg }}
    />
  )
}
